<script setup lang="ts">import { computed } from 'vue'; import { formatMoney } from '../../utils/formatters'; const props = defineProps<{ items: Array<{ label: string; total: string }> }>(); const maximum = computed(() => Math.max(1, ...props.items.map((item) => Number(item.total))));</script>
<template><div class="space-y-3"><div v-for="item in items" :key="item.label" class="grid min-w-0 grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-2 text-sm sm:grid-cols-[minmax(7rem,auto)_minmax(0,1fr)_auto]"><span class="min-w-0 truncate">{{ item.label }}</span><div class="col-span-2 h-3 min-w-0 overflow-hidden rounded-full bg-slate-100 sm:col-span-1"><div class="h-full rounded-full bg-brand-500" :style="{ width: `${Math.max(2, Number(item.total) / maximum * 100)}%` }" /></div><span class="row-start-1 whitespace-nowrap text-right text-xs tabular-nums sm:row-auto sm:text-sm">{{ formatMoney(item.total) }}</span></div></div></template>
